package server

import (
	"reflect"
	"runtime"
	"strings"
	"testing"
)

// TestRestServicesImplementAllMethods 检查 NewRestServer 收的每个 *XxxService 都自己实现了
// 嵌入接口（生成的 XxxServiceHTTPServer 等）的全部方法。
//
// Service 嵌入生成的接口只是为了少写方法也能编译：漏写的方法由 nil 接口提升而来，
// 编译能过、路由照常注册，请求一到就 nil 指针 panic，被 recovery 兜成 500。
// 这里用反射找出"只靠嵌入满足"的方法：编译器为提升方法生成的包装函数，
// runtime 报告的源文件是 <autogenerated>。
func TestRestServicesImplementAllMethods(t *testing.T) {
	ctor := reflect.TypeOf(NewRestServer)
	checked := 0
	for i := 0; i < ctor.NumIn(); i++ {
		pt := ctor.In(i)
		if pt.Kind() != reflect.Pointer || pt.Elem().Kind() != reflect.Struct ||
			!strings.HasSuffix(pt.Elem().Name(), "Service") {
			continue
		}
		checked++
		for _, missing := range methodsOnlyFromEmbedding(pt) {
			if handWrittenRoutes[pt.Elem().Name()+"."+missing] {
				continue
			}
			t.Errorf("%s 没有实现 %s：只靠嵌入接口满足，调用时会 nil panic", pt.Elem().Name(), missing)
		}
	}
	if checked == 0 {
		t.Fatal("NewRestServer 形参里没找到任何 *XxxService，检查逻辑失效")
	}
}

// handWrittenRoutes 由手写 HTTP handler 处理、不经生成接口方法的路由，豁免检查。
// 上传要流式读 multipart，i_file_transfer_http.pb.go 里的 handler 直接调用
// FileTransferService 的 UploadFile，不会走到这两个接口方法。
var handWrittenRoutes = map[string]bool{
	"FileTransferService.FileTransferServiceHTTPServer.PostUploadFile": true,
	"FileTransferService.FileTransferServiceHTTPServer.PutUploadFile":  true,
}

// methodsOnlyFromEmbedding 返回 ptr 的嵌入接口里，没有被具体类型声明的方法（"接口.方法"）。
func methodsOnlyFromEmbedding(ptr reflect.Type) []string {
	st := ptr.Elem()
	var missing []string
	for f := 0; f < st.NumField(); f++ {
		field := st.Field(f)
		if !field.Anonymous || field.Type.Kind() != reflect.Interface {
			continue
		}
		for m := 0; m < field.Type.NumMethod(); m++ {
			name := field.Type.Method(m).Name
			if !declaredOn(ptr, name) && !declaredOn(st, name) {
				missing = append(missing, field.Type.Name()+"."+name)
			}
		}
	}
	return missing
}

// declaredOn 报告 typ 的方法 name 是否为源码里真实声明的（而非编译器生成的提升/包装方法）。
func declaredOn(typ reflect.Type, name string) bool {
	m, ok := typ.MethodByName(name)
	if !ok {
		return false
	}
	fn := runtime.FuncForPC(m.Func.Pointer())
	if fn == nil {
		return false
	}
	file, _ := fn.FileLine(fn.Entry())
	return file != "<autogenerated>"
}

// TestMethodsOnlyFromEmbedding 自检：漏写的方法必须被识别，写了的不能误报。
func TestMethodsOnlyFromEmbedding(t *testing.T) {
	got := methodsOnlyFromEmbedding(reflect.TypeOf(&partialService{}))
	if len(got) != 1 || got[0] != "probeAPI.Delete" {
		t.Fatalf("want [probeAPI.Delete], got %v", got)
	}
}

type probeAPI interface {
	Get() error
	Delete() error
}

type partialService struct{ probeAPI }

func (s *partialService) Get() error { return nil }
